        Some(self.interpolated_time_of_day.map_or(time_of_day, |tod| {
            if (tod - time_of_day).abs() > max_lerp_period {
                time_of_day
            } else {
                Lerp::lerp(tod, time_of_day, dt as f64)
            }
        }));
    let time_of_day = self.interpolated_time_of_day.unwrap_or(time_of_day);
    let focus_pos = self.camera.get_focus_pos();
    let focus_off = focus_pos.map(|e| e.trunc());

    let step = 0.5 * dt;
    self.screen_fade = if step > (self.screen_fade - self.screen_fade_tgt).abs() {
        self.screen_fade_tgt
    } else {
        self.screen_fade + (self.screen_fade_tgt - self.screen_fade).signum() * step
    };

    let player_dir = client
        .state()
        .ecs()
        .read_storage::<comp::Ori>()
        .get(client.entity())
        .copied()
        .unwrap_or_default()
        .look_dir()
        .to_vec();

    // atan2(x,y) instead of (y,x) so that north is 0
    let player_mmap_ori = player_dir.x.atan2(player_dir.y)
        - if !mmap_face_north {
            // If the map follows the camera, subtract the camera's angle from player angle
            self.camera.get_orientation().x
        } else {
            0.0
        };

    // Update global constants.
    renderer.update_consts(&mut self.data.globals, &[Globals::new(
        view_mat,
        proj_mat,
        cam_pos,
        focus_pos,
        self.loaded_distance,
        self.lod.get_data().tgt_detail as f32,
        self.map_bounds,
        time_of_day,
        scene_data.state.get_time(),
        self.local_time,
        renderer.resolution().as_(),
        renderer.internal_resolution().as_(),
        Vec2::new(SHADOW_NEAR, SHADOW_FAR),
        lights.len(),
        shadows.len(),
        NUM_DIRECTED_LIGHTS,
        scene_data
            .state
            .terrain()
            .get((cam_pos + focus_off).map(|e| e.floor() as i32))
            .ok()
            // Don't block the camera's view in solid blocks if the player is a moderator
            .filter(|b| !(b.is_filled() && client.is_moderator()))
            .map(|b| b.kind())
            .unwrap_or(BlockKind::Air),
        self.select_pos.map(|e| e - focus_off.map(|e| e as i32)),
        scene_data.gamma,
        scene_data.exposure,
        self.last_lightning.unwrap_or((Vec3::zero(), -1000.0)),
        self.wind_vel,
        scene_data.ambiance,
        self.camera.get_mode(),
        scene_data.sprite_render_distance - 20.0,
        player_mmap_ori,
        self.screen_fade,
    )]);
    renderer.update_clouds_locals(CloudsLocals::new(proj_mat_inv, view_mat_inv));
    renderer.update_postprocess_locals(PostProcessLocals::new(proj_mat_inv, view_mat_inv));

    // Maintain LoD.
    self.lod.maintain(renderer, client, focus_pos, &self.camera);

    // Maintain tethers.
    self.tether_mgr.maintain(renderer, client, focus_pos);

    // Maintain debug shapes
    self.debug.maintain(renderer);

    // Maintain the terrain.
    let (
        _visible_bounds,
        visible_light_volume,
        visible_psr_bounds,
        visible_occlusion_volume,
        visible_por_bounds,
    ) = self.terrain.maintain(
        renderer,
        scene_data,
        focus_pos,
        self.loaded_distance,
        &self.camera,
    );

    // Maintain the figures.
    let _figure_bounds = self.figure_mgr.maintain(
        renderer,
        &mut self.trail_mgr,
        scene_data,
        visible_psr_bounds,
        visible_por_bounds,
        &self.camera,
        Some(&self.terrain),
    );

    let fov = self.camera.get_effective_fov();
    let aspect_ratio = self.camera.get_aspect_ratio();
    let view_dir = ((focus_pos.map(f32::fract)) - cam_pos).normalized();

    // We need to compute these offset matrices to transform world space coordinates
    // to the translated ones we use when multiplying by the light space
    // matrix; this helps avoid precision loss during the
                HudEvent::LeaveGroup => {
                    self.client.borrow_mut().leave_group();
                },
                HudEvent::AssignLeader(uid) => {
                    self.client.borrow_mut().assign_group_leader(uid);
                },
                HudEvent::ChangeAbility(slot, new_ability) => {
                    self.client.borrow_mut().change_ability(slot, new_ability);
                },
                HudEvent::SettingsChange(settings_change) => {
                    settings_change.process(global_state, self);
                },
                HudEvent::AcknowledgePersistenceLoadError => {
                    self.metadata.skill_set_persistence_load_error = None;
                },
                HudEvent::MapMarkerEvent(event) => {
                    self.client.borrow_mut().map_marker_event(event);
                },
                HudEvent::Dialogue(target, dialogue) => {
                    self.client.borrow_mut().perform_dialogue(target, dialogue);
                },
                HudEvent::SetBattleMode(mode) => {
                    self.client.borrow_mut().set_battle_mode(mode);
                },
            }
        }

        {
            let client = self.client.borrow();
            let scene_data = SceneData {
                client: &client,
                state: client.state(),
                viewpoint_entity,
                mutable_viewpoint: mutable_viewpoint || self.free_look,
                // Only highlight if interactable
                target_entities: &self.interactables.entities,
                loaded_distance: client.loaded_distance(),
                terrain_view_distance: client.view_distance().unwrap_or(1),
                entity_view_distance: client
                    .view_distance()
                    .unwrap_or(1)
                    .min(global_state.settings.graphics.entity_view_distance),
                tick: client.get_tick(),
                gamma: global_state.settings.graphics.gamma,
                exposure: global_state.settings.graphics.exposure,
                ambiance: global_state.settings.graphics.ambiance,
                mouse_smoothing: global_state.settings.gameplay.smooth_pan_enable,
                sprite_render_distance: global_state.settings.graphics.sprite_render_distance
                    as f32,
                particles_enabled: global_state.settings.graphics.particles_enabled,
                particles_chance: global_state.settings.graphics.particles_chance,
                weapon_trails_enabled: global_state.settings.graphics.weapon_trails_enabled,
                flashing_lights_enabled: global_state
                    .settings
                    .graphics
                    .render_mode
                    .flashing_lights_enabled,
                figure_lod_render_distance: global_state
                    .settings
                    .graphics
                    .figure_lod_render_distance
                    as f32,
                is_aiming,
                interpolated_time_of_day: self.scene.interpolated_time_of_day,
                wind_vel: self.scene.wind_vel,
            };

            // Runs if either in a multiplayer server or the singleplayer server is unpaused
            if !global_state.paused() {
                self.scene.maintain(
                    global_state.window.renderer_mut(),
                    &mut global_state.audio,
                    &scene_data,
                    &client,
                    &global_state.settings,
                    global_state.settings.interface.minimap_face_north,
                );

                // Process outcomes from client
                for outcome in outcomes {
                    self.scene
                        .handle_outcome(&outcome, &scene_data, &mut global_state.audio);
                    self.hud.handle_outcome(&outcome, &scene_data, global_state);
                }
            }
        }

        // Clean things up after the tick.
        self.cleanup();

        PlayStateResult::Continue
    } else if client_registered && client_presence.is_none() {
        // If the client cannot enter the game but spectate, pop the play state instead
        // of going back to character selection.
        if client_type.can_spectate() && !client_type.can_enter_character() {
            // Go back to the main menu state
            PlayStateResult::Pop
        } else {
            PlayStateResult::Switch(Box::new(CharSelectionState::new(
                global_state,
                Rc::clone(&self.client),
                Rc::clone(&self.hud.persisted_state),
            )))
        }
    } else {
        error!("Client not in the expected state, exiting session play state");
        PlayStateResult::Pop
    }
}

